function sanitize(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/'/g, "''").trim();
}

const b = items[0].json.body || items[0].json;

const bedrag = parseFloat(b.bedrag) || 0;
const btw_pct = parseFloat(b.btw) || 0;
const btw_bedrag = Math.round(bedrag * btw_pct) / 100;
const totaal = Math.round((bedrag + btw_bedrag) * 100) / 100;

return [{ json: {
  leverancier:   sanitize(b.leverancier),
  factuurnummer: sanitize(b.factuurnummer),
  datum:         sanitize(b.datum) || new Date().toISOString().split('T')[0],
  omschrijving:  sanitize(b.omschrijving),
  bedrag:        bedrag,
  btw_pct:       btw_pct,
  btw_bedrag:    btw_bedrag,
  totaal:        totaal,
  grootboek:     sanitize(b.grootboek)
}}];
